import re

_UNITS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_PART = re.compile(r"([0-9]+)([dhms])", re.IGNORECASE)
_ORDER = {unit: index for index, unit in enumerate("dhms")}


def parse(text):
    """Parse a duration like '1h30m', '2D 5m' or '45s' into seconds.

    The units are d, h, m and s, in upper or lower case. Each unit may appear at most
    once, largest unit first, each with a whole number in front of it. Spaces around
    and between the parts are allowed. Anything else, including an empty string,
    raises ValueError.
    """
    if not isinstance(text, str):
        raise ValueError(f"bad duration: {text!r}")

    stripped = text.strip()
    if not stripped:
        raise ValueError(f"bad duration: {text!r}")

    parts = []
    position = 0
    last_unit = -1
    for match in _PART.finditer(stripped):
        if stripped[position:match.start()].strip():
            raise ValueError(f"bad duration: {text!r}")
        amount = int(match.group(1))
        unit = match.group(2).lower()
        order = _ORDER[unit]
        if order <= last_unit:
            raise ValueError(f"bad duration: {text!r}")
        last_unit = order
        parts.append((amount, unit))
        position = match.end()

    if not parts or stripped[position:].strip():
        raise ValueError(f"bad duration: {text!r}")

    return sum(amount * _UNITS[unit] for amount, unit in parts)


def format_duration(seconds):
    """Format seconds the way parse() reads them, e.g. 5400 -> '1h30m' and 0 -> '0s'.

    Negative seconds raise ValueError.
    """
    if seconds < 0:
        raise ValueError("negative duration")
    if seconds == 0:
        return "0s"
    out = []
    for unit, size in _UNITS.items():
        if seconds >= size:
            out.append(f"{seconds // size}{unit}")
            seconds %= size
    return "".join(out)

